#include "EventToNotificationAdapter.h"
EventToNotificationAdapter::EventToNotificationAdapter(EventNotificationRegistry& r,EventNotificationFormatter& f,NotificationRuntime& n):registry_(r),formatter_(f),runtime_(n),payload_{},nextId_(1U),forwarded_(0U),ignored_(0U),failed_(0U),last_(RuntimeIntegrationResult::NOT_INITIALIZED),initialized_(false){}
RuntimeIntegrationResult EventToNotificationAdapter::begin(){for(size_t i=0U;i<registry_.size();++i)if(registry_.at(i)==nullptr||!registry_.at(i)->isValid()){last_=RuntimeIntegrationResult::INTERNAL_ERROR;return last_;}registry_.lock();initialized_=true;last_=RuntimeIntegrationResult::SUCCESS;return last_;}bool EventToNotificationAdapter::isInitialized()const{return initialized_;}
void EventToNotificationAdapter::advanceNotificationId(){++nextId_;if(nextId_==0U)nextId_=1U;}
RuntimeIntegrationResult EventToNotificationAdapter::finish(RuntimeIntegrationResult r){last_=r;if(r==RuntimeIntegrationResult::SUCCESS||r==RuntimeIntegrationResult::ACCEPTED||r==RuntimeIntegrationResult::IN_PROGRESS)saturatingIncrement(forwarded_);else if(r==RuntimeIntegrationResult::IGNORED||r==RuntimeIntegrationResult::FILTERED||r==RuntimeIntegrationResult::MAPPING_DISABLED)saturatingIncrement(ignored_);else if(r==RuntimeIntegrationResult::RETRY_LATER||r==RuntimeIntegrationResult::REJECTED||r==RuntimeIntegrationResult::FAILED||r==RuntimeIntegrationResult::INTERNAL_ERROR||r==RuntimeIntegrationResult::INVALID_INPUT)saturatingIncrement(failed_);return r;}
RuntimeIntegrationResult EventToNotificationAdapter::mapRuntimeResult(NotificationRuntimeResult r){switch(r){case NotificationRuntimeResult::SUCCESS:return RuntimeIntegrationResult::SUCCESS;case NotificationRuntimeResult::ACCEPTED:return RuntimeIntegrationResult::ACCEPTED;case NotificationRuntimeResult::IN_PROGRESS:return RuntimeIntegrationResult::IN_PROGRESS;case NotificationRuntimeResult::RETRY_LATER:case NotificationRuntimeResult::CHANNEL_BUSY:return RuntimeIntegrationResult::RETRY_LATER;case NotificationRuntimeResult::NO_CHANGE:return RuntimeIntegrationResult::NO_CHANGE;case NotificationRuntimeResult::SINK_REJECTED:return RuntimeIntegrationResult::REJECTED;case NotificationRuntimeResult::CANCELLED:case NotificationRuntimeResult::EXPIRED:case NotificationRuntimeResult::SINK_FAILED:case NotificationRuntimeResult::NOT_INITIALIZED:case NotificationRuntimeResult::INVALID_ARGUMENT:case NotificationRuntimeResult::INVALID_NOTIFICATION:case NotificationRuntimeResult::INVALID_CHANNEL:case NotificationRuntimeResult::CHANNEL_NOT_FOUND:case NotificationRuntimeResult::CHANNEL_DISABLED:case NotificationRuntimeResult::REGISTRY_FULL:case NotificationRuntimeResult::REGISTRY_LOCKED:case NotificationRuntimeResult::DUPLICATE_CHANNEL_ID:return RuntimeIntegrationResult::FAILED;case NotificationRuntimeResult::INTERNAL_ERROR:case NotificationRuntimeResult::COUNT:return RuntimeIntegrationResult::INTERNAL_ERROR;default:return RuntimeIntegrationResult::INTERNAL_ERROR;}}
RuntimeIntegrationResult EventToNotificationAdapter::onEvent(const Event& e,NotificationTimestamp now){if(!initialized_)return finish(RuntimeIntegrationResult::NOT_INITIALIZED);if(!e.isValid())return finish(RuntimeIntegrationResult::INVALID_INPUT);const EventNotificationMapping* m=registry_.find(e.type);if(m==nullptr)return finish(RuntimeIntegrationResult::IGNORED);if(!m->enabled())return finish(RuntimeIntegrationResult::MAPPING_DISABLED);if(static_cast<uint8_t>(e.severity)<static_cast<uint8_t>(m->minimumSeverity()))return finish(RuntimeIntegrationResult::FILTERED);size_t length=0U;const EventNotificationFormatResult fr=formatter_.format(e,payload_,sizeof(payload_),length);if(!isValidEventNotificationFormatResult(fr))return finish(RuntimeIntegrationResult::INTERNAL_ERROR);if(fr==EventNotificationFormatResult::NO_CONTENT)return finish(RuntimeIntegrationResult::IGNORED);if(fr==EventNotificationFormatResult::INVALID_EVENT)return finish(RuntimeIntegrationResult::INVALID_INPUT);if(fr==EventNotificationFormatResult::BUFFER_TOO_SMALL||fr==EventNotificationFormatResult::FAILED)return finish(RuntimeIntegrationResult::FAILED);if(length==0U)return finish(RuntimeIntegrationResult::IGNORED);if(length>sizeof(payload_))return finish(RuntimeIntegrationResult::INTERNAL_ERROR);const NotificationId id=nextId_;const NotificationMessage message=NotificationMessage::create(id,m->channelId(),m->priority(),e.timestampMs,m->ttlMs(),m->target(),m->targetLength(),payload_,length);if(!message.isValid())return finish(RuntimeIntegrationResult::INTERNAL_ERROR);advanceNotificationId();return finish(mapRuntimeResult(runtime_.send(message,now)));}
EventHandleResult EventToNotificationAdapter::handle(const Event& e){(void)e;finish(RuntimeIntegrationResult::INVALID_INPUT);return EventHandleResult::FAILED;}
uint32_t EventToNotificationAdapter::forwardedCount()const{return forwarded_;}uint32_t EventToNotificationAdapter::ignoredCount()const{return ignored_;}uint32_t EventToNotificationAdapter::failedCount()const{return failed_;}NotificationId EventToNotificationAdapter::nextNotificationId()const{return nextId_;}RuntimeIntegrationResult EventToNotificationAdapter::lastResult()const{return last_;}
